 *
 * @return int 0, 1 or -1
 */
public static function compareDateIntervals(DateInterval $first, DateInterval $second): int
{
    $current = Carbon::now();
    $passed = $current->avoidMutation()->add($second);
    $current->add($first);

    return $current <=> $passed;
}

